const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const paths={waves:'M3 8c3-4 6 4 9 0s6 4 9 0M3 15c3-4 6 4 9 0s6 4 9 0',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M4 4v16h17M8 15l4-5 4 2 5-7',sliders:'M6 3v7m0 4v7M18 3v11m0 4v3M3 10h6v4H3zM15 14h6v4h-6z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',cloud:'M6 18h12a4 4 0 0 0 0-8 6 6 0 0 0-11-2 5 5 0 0 0-1 10',camera:'M3 6h5l2-3h4l2 3h5v15H3zM16 13a4 4 0 1 0-8 0 4 4 0 0 0 8 0',brain:'M9 4a3 3 0 0 0-5 3 4 4 0 0 0-1 7 4 4 0 0 0 6 5m6-15a3 3 0 0 1 5 3 4 4 0 0 1 1 7 4 4 0 0 1-6 5M9 3v18m6-18v18M6 10h3m6 5h3',settings:'m9 3-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-2v-4l2-2-2-4-3-1-1-3zM15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0',thermo:'M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0M12 8v9',drop:'M12 3s7 8 7 12a7 7 0 0 1-14 0c0-4 7-12 7-12M8 15c0 2 1 3 3 3',shield:'M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6zM8 12l3 3 5-6',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',refresh:'M20 7a9 9 0 1 0 1 8M20 2v6h-6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',pump:'M4 8h12v12H4zM7 4h6v4M16 12h5v5h-5M8 13h4v3H8z',fan:'M12 12c-8-6-8-10-3-10 4 0 4 5 3 10m0 0c8-6 12-5 10 0-2 4-6 2-10 0m0 0c0 10-3 12-6 8-3-4 1-6 6-8',auto:'m14 2-9 12h7l-2 8 9-12h-7z',clock:'M12 7v6l4 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',check:'m5 12 4 4L20 5',alert:'m12 3 10 18H2zM12 9v5m0 3v1',database:'M3 6c0-5 18-5 18 0s-18 5-18 0v12c0 5 18 5 18 0V6M3 12c0 5 18 5 18 0',menu:'M3 6h18M3 12h18M3 18h18',wifi:'M2 8c6-6 14-6 20 0M5 12c4-4 10-4 14 0M9 16c2-2 4-2 6 0M12 20h.01',wind:'M3 7h12c5 0 5-6 1-6M3 12h16c5 0 5 7 1 7M3 17h8c5 0 5 6 1 6',close:'m6 6 12 12M6 18 18 6',link:'m9 15 6-6M7 14l-2 2a4 4 0 0 0 5 5l4-4m-4-10 4-4a4 4 0 0 1 5 5l-2 2'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,n=1)=>Number.isFinite(v)?new Intl.NumberFormat('vi-VN',{minimumFractionDigits:n,maximumFractionDigits:n}).format(v):'—';
const dt=(d,full=false)=>d?new Intl.DateTimeFormat('vi-VN',{...(full?{day:'2-digit',month:'2-digit'}:{}),hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(d)):'—';
const ago=d=>!d?'chưa có dữ liệu':Date.now()-new Date(d)<60000?'vừa cập nhật':`${Math.max(1,Math.floor((Date.now()-new Date(d))/60000))} phút trước`;
const labels={temp:'Nhiệt độ nước',ph:'Độ pH',turb:'Độ đục',humidity:'Độ ẩm tại ao'};
const units={temp:'°C',ph:'pH',turb:'%',humidity:'%'};
const navs=[['overview','grid','Tổng quan'],['history','chart','Lịch sử dữ liệu'],['controls','sliders','Điều khiển'],['alerts','bell','Cảnh báo'],['weather','sun','Thời tiết'],['camera','camera','Camera & an ninh'],['ai','brain','Phân tích & dự báo'],['settings','settings','Cài đặt']];
let S=null,page='overview',metric='temp',hours=24,historyPage=1,alertFilter='all',busy=false,renderId=0,lastRows=[],toastTimer,streaming=false,aiMetric='temp',pollFailures=0;
let chartSession='latest', chartSessions=[];
const stamp=d=>new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(d));
const nowRange=()=>({start:Date.now()-hours*3600000,end:Date.now()});
async function api(path,body){const r=await fetch(path,{...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-App-Token':S.token},body:JSON.stringify(body)})});let data;try{data=await r.json();}catch{throw Error('Máy chủ chưa sẵn sàng.');}if(!r.ok)throw Error(data.error||(data.status==='unknown'?'Chưa rõ kết quả lệnh. Không tự gửi lại.':'Không thể hoàn tất thao tác.'));return data;}
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.className=error?'error':'';el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',6000);}
function observed(key){const telemetry=S.latest[key],rpc=S.rpcStates?.[key];return rpc&&(!telemetry||new Date(rpc.observedAt)>new Date(telemetry.observedAt))?rpc:telemetry;}
function fresh(key){if(pollFailures)return false;const p=observed(key);return p&&Date.now()-new Date(p.observedAt)<30000;}
function activeAlerts(){return S.alerts.filter(a=>a.active&&!a.acknowledgedAt);}
function pill(text,type=''){return `<span class="status-pill ${type}">${type==='critical'?icon('alert',10):'<i class="dot"></i>'}${esc(text)}</span>`;}
function metricState(key){const p=S.latest[key],t=S.settings.thresholds;if(!p)return ['Chưa có cảm biến','neutral'];if(!fresh(key))return ['Dữ liệu đã cũ','warning'];if(p.quality!=='valid')return ['Cần kiểm tra','warning'];const v=p.value;return key==='temp'&&(v<t.tempMin||v>t.tempMax)||key==='ph'&&(v<t.phMin||v>t.phMax)||key==='turb'&&v>t.turbMax?['Vượt ngưỡng','warning']:['Trong ngưỡng',''];}
function demoBanner(){return S.mode==='demo'?`<div class="demo-banner"><span>${icon('database',12)} <strong>KHÔNG GIAN MÔ PHỎNG</strong> · Dữ liệu cảm biến và thao tác điều khiển là minh họa, chưa kết nối mạch thật.</span><button class="banner-link" data-nav="settings">Cấu hình kết nối ${icon('arrow',10)}</button></div>`:'';}
function shell(){
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('waves',27)}</span><div><strong>AoTom<span style="display:none"> Nexus</span></strong><small>NEXUS WORKSPACE</small></div></div><div class="nav-caption">VẬN HÀNH & DỮ LIỆU</div><nav class="nav" aria-label="Điều hướng chính">${navs.map(([id,i,l],n)=>`${n===7?'<div class="nav-sep"></div>':''}<button data-nav="${id}" class="${page===id?'active':''}">${icon(i,17)}<span>${l}</span>${id==='alerts'?'<span class="badge" id="alert-count">0</span>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="device-note"><strong><i class="dot" id="side-dot"></i><span id="side-status">ESP32 DevKit V1</span></strong><p id="side-sync">Đang đồng bộ thiết bị</p></div><div class="side-footer"><div class="avatar">N4</div><div><strong>Nhóm dự án IoT</strong><small>Không gian cục bộ</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" aria-label="Mở menu" id="menu">${icon('menu',17)}</button><span>Không gian làm việc</span>${icon('chevron',11)}<b id="breadcrumb">Tổng quan</b></div><div class="top-actions"><span class="top-date">${new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date())}</span><button class="icon-btn" data-nav="alerts" aria-label="Xem cảnh báo">${icon('bell',16)}<i class="notify-dot" hidden></i></button><div class="avatar">N4</div></div></header><main class="content" id="main"></main><nav class="bottom-nav" aria-label="Điều hướng điện thoại"><button data-nav="overview">${icon('grid',20)}Tổng quan</button><button data-nav="controls">${icon('sliders',20)}Điều khiển</button><button data-nav="alerts">${icon('bell',20)}Cảnh báo</button><button id="more-menu">${icon('menu',20)}Thêm</button></nav></div></div>`;
 chrome();render();
}
function chrome(){
 if(!S)return;$$('.laser-status').forEach(el=>{const t=document.createElement('div');t.innerHTML=laserStatus();morph(el,t.firstElementChild);});$('.notify-dot').hidden=activeAlerts().length===0;$('#alert-count').textContent=activeAlerts().length;$('#side-sync').textContent=S.mode==='demo'?'Chế độ mô phỏng · RAM':S.connection.connected?'ThingsBoard · '+ago(S.connection.lastSyncAt):'Chưa kết nối ThingsBoard';
 $('#side-dot').className='dot '+(S.connection.deviceFresh?'':'orange');
 $('#breadcrumb').textContent=navs.find(x=>x[0]===page)[2];$$('.nav button,.bottom-nav [data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===page);el.setAttribute('aria-current',el.dataset.nav===page?'page':'false');});
}
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">AOTOM NEXUS / ${esc(S.settings.pondName)}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="head-actions">${actions}</div></div>${demoBanner()}${S.connection.error?`<div class="error-banner">${icon('alert',13)} ${esc(S.connection.error)}</div>`:''}`;}
const footer=()=>`<footer class="footer"><span>${icon('waves',11)} AoTom Nexus · Hệ thống giám sát ao nuôi</span><span><i class="dot"></i> ${S.mode==='demo'?'Mô phỏng cục bộ':'ThingsBoard → '+S.connection.database} · Giờ Việt Nam</span></footer>`;
function spark(color='#8da679'){return `<svg class="spark" viewBox="0 0 70 25" fill="none" aria-hidden="true"><path d="m0 20 6-3 6 1 6-7 6 3 6-8 6 5 6-3 6 2 6-7 6 1 8-2" stroke="${color}" stroke-width="1.4"/></svg>`;}
function metricCard(key,ico,color=''){
 const p=S.latest[key],st=metricState(key),val=p?.quality==='valid'?p.value:null;
 return `<article class="card metric-card ${color}"><div class="metric-top"><span>${labels[key]}</span><span class="metric-icon">${icon(ico,16)}</span></div><div class="metric-value">${fmt(val,key==='ph'?2:1)}<span>${units[key]}</span></div><div class="metric-range">Ngưỡng: ${waterBounds(key,S.settings.thresholds).map(v=>fmt(v,key==='ph'?2:1)).join(' – ')} ${units[key]}</div><div class="metric-foot">${pill(...st)}<span>${p?ago(p.observedAt):'Chưa lắp cảm biến'}</span></div></article>`;
}
function chartCard(){return `<section class="card chart-card"><div class="card-head"><div><h2>Diễn biến chất lượng nước</h2><p class="card-desc">${S.mode==='demo'?'Dữ liệu mô phỏng':'Dữ liệu đo gốc'} · xem riêng từng đợt đo</p></div><span class="status-pill neutral">Giờ Việt Nam</span></div><div class="metric-tabs" role="group" aria-label="Chỉ số biểu đồ">${['temp','ph','turb'].map(k=>`<button class="${metric===k?'selected':''}" data-metric="${k}">${labels[k]}</button>`).join('')}</div><div class="session-controls" id="session-controls"><label class="session-picker" for="chart-session">Đợt đo<select id="chart-session" disabled><option>Đang tìm các đợt đo…</option></select></label><div class="session-buttons"><button class="icon-btn session-prev" data-session-step="-1" aria-label="Đợt đo trước" title="Đợt đo trước" disabled>${icon('chevron',14)}</button><button class="icon-btn" data-session-step="1" aria-label="Đợt đo sau" title="Đợt đo sau" disabled>${icon('chevron',14)}</button><button class="btn small" data-session-latest disabled>Đợt mới nhất</button></div></div><div class="session-range" id="session-range" aria-live="polite">Mỗi đợt được tách khi dữ liệu gián đoạn hơn 5 phút.</div><div class="chart-wrap" id="chart-area"><div class="empty-state">Đang tải biểu đồ…</div></div><div class="chart-footer"><i class="dot"></i><span id="chart-meta">Chỉ vẽ dữ liệu của đợt đang chọn.</span></div></section>`;}
function paintSessionControls(result){
 chartSessions=result.sessions;
 const list=chartSessions,select=$('#chart-session'),selected=chartSession==='latest'?list.at(-1):list.find(x=>x.id===chartSession);
 const selectedIndex=list.indexOf(selected);
 select.disabled=!list.length;
 select.innerHTML=list.length?list.slice().reverse().map((x,i)=>`<option value="${i===0?'latest':esc(x.id)}">${i===0?'Đợt gần nhất':'Đợt '+(list.length-i)} · ${stamp(x.startedAt)} → ${dt(x.endedAt)}</option>`).join(''):'<option value="latest">Chưa có đợt đo trong 7 ngày gần nhất</option>';
 if(chartSession!=='latest'&&!selected)select.insertAdjacentHTML('beforeend',`<option value="${esc(chartSession)}">Đợt đang chọn đã ngoài phạm vi tra cứu</option>`);
 select.value=chartSession;
 $('[data-session-step="-1"]').disabled=selectedIndex<=0;
 $('[data-session-step="1"]').disabled=selectedIndex<0||selectedIndex>=list.length-1;
 $('[data-session-latest]').disabled=!list.length||chartSession==='latest';
 const range=$('#session-range');
 range.classList.remove('session-stale');
 if(selected){
   const isLatest=selectedIndex===list.length-1;
   const stale=isLatest&&new Date(result.now)-new Date(selected.endedAt)>30000;
   range.classList.toggle('session-stale',stale);
   range.innerHTML=`<strong>${chartSession==='latest'?'Đợt gần nhất':'Đang xem đợt cũ'}</strong><span>${stamp(selected.startedAt)} → ${stamp(selected.endedAt)}</span><small>${stale?'Chưa nhận dữ liệu mới trong 30 giây gần nhất.':chartSession==='latest'?'Tự cập nhật khi có dữ liệu mới.':'Giữ nguyên đợt này khi dữ liệu mới được gửi lên.'}${result.truncated?' Phạm vi tra cứu đã chạm giới hạn 50.000 bản ghi.':''}</small>`;
 }else range.textContent=list.length?'Đợt đã ngoài phạm vi tra cứu. Bấm Đợt mới nhất để tiếp tục.':'Chưa có dữ liệu để tách đợt đo. Kiểm tra đồng bộ thiết bị.';
 return selected;
}

function controlRows(){return [['pump','pump','Bơm oxy','setPump'],['fan','fan','Quạt nước','setFan'],['auto','auto','Chế độ tự động','setAuto']].map(([key,i,label,method])=>{
 const p=observed(key),isFresh=fresh(key),on=p?.value===1,disabled=busy||pollFailures>0||!isFresh||S.mode==='live'&&!S.connection.connected;
 return `<div class="control-row"><div class="control-icon">${icon(i,18)}</div><div><strong>${label}</strong><small>${!p?'Chưa có trạng thái':!isFresh?'Trạng thái đã cũ':on?'Đang bật':'Đang tắt'}${p?.source==='rpc'?' · RPC':''}</small></div><button class="btn device-action ${on?'on':''}"  aria-label="${label}" data-command="${method}" data-value="${!on}" ${disabled?'disabled':''}>${busy?'Đang gửi…':!isFresh?'Chưa rõ':on?'Tắt':'Bật'}</button>${commandFeedback(method)}</div>`;
}).join('');}
function controlCard(){return `<section class="card control-card"><div class="card-head"><h2>Điều khiển thiết bị</h2>${icon('sliders',15)}</div><div class="control-intro">${S.mode==='demo'?'Công tắc minh họa · không gửi lệnh thật':'Trạng thái từ telemetry / phản hồi RPC'}</div><div id="control-rows">${controlRows()}</div><div class="control-foot">Điều khiển bơm / quạt sẽ tắt Auto trên ESP32.</div></section>`;}
function pondScene(){return `<svg viewBox="0 0 420 200" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Sơ đồ minh họa ao nuôi, không phải ảnh camera"><rect width="420" height="200" fill="#d9e3cc"/><path d="M0 150 420 74v40L0 190z" fill="#cbd7b9"/><path d="M0 24 320 200h70L0 0z" fill="#b9c9a9"/><path d="m46 30 226 7 86 102-257 20z" fill="#b7c9a8"/><path d="m56 36 207 7 77 88-234 18z" fill="#9eb9a0"/><path d="m63 43 193 6 67 76-212 16z" fill="#afc8b5"/><path d="m74 69 195 8M85 94l202 4m-190 18 206 4" stroke="#c7dbcb" stroke-width="1" opacity=".6"/><path d="m267 30 92-5 48 57-91 15z" fill="#a8bd99"/><path d="m275 34 81-3 41 47-78 13z" fill="#b5ceb5"/><g fill="#92aa80"><circle cx="20" cy="56" r="16"/><circle cx="39" cy="173" r="20"/><circle cx="384" cy="153" r="24"/><circle cx="405" cy="122" r="15"/><circle cx="208" cy="184" r="10"/></g><path d="m170 98 15-5 8 7-15 5z" fill="#eef1d9"/><path d="m180 85 1 24m-12-11 23-1" stroke="#6b906e" stroke-width="2"/><path d="m293 146 33-3 20 19-34 5z" fill="#b2bca0"/><path d="m292 142 18-11 24 11-21 9z" fill="#8a9f7c"/></svg>`;}
function sampleWeather(){return {sample:true,fetchedAt:null,hours:Array.from({length:24},(_,i)=>({targetAt:new Date(Date.now()+i*3600000),airTemp:29+Math.sin(i/5)*3,humidity:78+i%8,rain:i>=4&&i<=6?18:0,rainProbability:i>=4&&i<=6?80:20,wind:12+i%5})),risks:[]};}
function weatherData(){return S.weather?{...S.weather,hours:S.weather.hours.filter(h=>new Date(h.targetAt).getTime()>=Date.now()-3600000)}:(S.mode==='demo'?sampleWeather():null);}

function waterBounds(key,t){return key==='temp'?[t.tempMin,t.tempMax]:key==='ph'?[t.phMin,t.phMax]:key==='turb'?[0,t.turbMax]:[null,null];}
function envelope(points){
 if(points.length<=500)return points;
 const size=Math.ceil(points.length/125),out=[];
 for(let i=0;i<points.length;i+=size){const b=points.slice(i,i+size);const picks=[b[0],b.reduce((a,p)=>p[1]<a[1]?p:a),b.reduce((a,p)=>p[1]>a[1]?p:a),b.at(-1)];out.push(...[...new Set(picks)].sort((a,b)=>a[0]-b[0]));}return out;
}
function overviewStatus(){return `<div class="system-status"><strong>${S.mode==='live'?'LIVE':'DEMO'} · ${esc(S.settings.pondName)}</strong><span>${pill(pollFailures?'Mất kết nối web':S.connection.connected?'ThingsBoard · '+(S.mode==='demo'?'mô phỏng':'đã kết nối'):'ThingsBoard · mất kết nối',pollFailures||!S.connection.connected?'warning':'')}</span><span>${pill(S.connection.deviceFresh&&!pollFailures?'ESP32 · dữ liệu mới':'ESP32 · dữ liệu cũ','neutral')}</span><span>Lưu trữ: ${esc(S.connection.database)}</span></div>`;}
function priorityAlerts(){const list=activeAlerts().slice().sort((a,b)=>(b.severity==='critical')-(a.severity==='critical'));return `<section class="priority-alert ${list.length?'attention':''}">${icon(list.length?'alert':'check',22)}<div><strong>${list.length?`${list.length} cảnh báo cần chú ý`:'Không có cảnh báo chưa xem đang diễn ra'}</strong><p>${list.length?esc(list[0].title):'Tiếp tục theo dõi các chỉ số và thời điểm đo.'}</p></div><button class="btn" data-nav="alerts">Xem cảnh báo ${icon('arrow',16)}</button></section>`;}
function laserStatus(){const p=S.latest.laser,known=fresh('laser')&&p?.quality==='valid'&&[0,1].includes(p.value);return '<span class="laser-status">'+pill(!known?'Laser · chưa rõ trạng thái':p.value===1?'Laser · tia bị cắt':'Laser · thông suốt',!known?'neutral':p.value===1?'critical':'')+'</span>';}
function cameraPreview(){const m=S.media[0];return m?`<img loading="lazy" src="/api/media/${encodeURIComponent(m._id)}" alt="Ảnh ao đã lưu"><span class="camera-label">Ảnh đã lưu · ${stamp(m.capturedAt)}</span>`:`<div class="empty-state">${icon('camera',32)}<strong>Chưa có ảnh đã lưu</strong><p>Mở camera để xem hoặc chụp ảnh.</p></div>`;}
function overview(){const w=weatherData(),h=w?.hours[0];return head('Tổng quan ao nuôi','Nắm bắt tình trạng nước và các hoạt động cần chú ý.',`<button class="btn" data-action="sync">${icon('refresh',16)} Đồng bộ ngay</button><button class="btn primary" data-nav="history">Xem lịch sử ${icon('arrow',16)}</button>`)+overviewStatus()+priorityAlerts()+`<div class="metric-grid water-metrics">${metricCard('temp','thermo')}${metricCard('ph','drop','blue')}${metricCard('turb','waves','amber')}</div><div class="main-grid">${chartCard()}${controlCard()}</div><div class="bottom-grid operations-bottom"><section class="card"><div class="card-head"><h2>Camera & an ninh</h2><button class="btn link" data-nav="camera">Mở camera ${icon('arrow',16)}</button></div><div class="camera-thumb">${cameraPreview()}</div><div class="camera-bottom">${laserStatus()}<span>Không phải ảnh trực tiếp</span></div></section><section class="card"><div class="card-head"><h2>Thời tiết tại ao</h2><button class="btn link" data-nav="weather">Chi tiết ${icon('arrow',16)}</button></div><div class="panel">${h?`<div class="weather-temp">${fmt(h.airTemp)}<small> °C không khí</small></div><p>Mưa ${fmt(h.rain)} mm/h · Gió ${fmt(h.wind)} km/h</p><p>${w.sample?'Dữ liệu minh họa':'Dự báo · lấy '+stamp(w.fetchedAt)}</p>`:'<p>Chưa có dự báo cho vị trí này.</p><button class="btn" data-nav="weather">Xem thời tiết</button>'}</div></section></div>`+footer();}
function commandFeedback(method){const c=S.commands.find(c=>c.method===method);if(!c)return '';const names={pending:'Đang chờ phản hồi',acknowledged:'ESP32 đã phản hồi',unknown:'Chưa rõ kết quả · không tự gửi lại',rejected:'Phản hồi khác yêu cầu',failed:'Gửi lệnh thất bại'};return `<p class="command-feedback ${['unknown','failed','rejected'].includes(c.status)?'warning':''}">${esc(names[c.status]||c.status)} · ${dt(c.completedAt||c.createdAt,true)}</p>`;}
function syncURL(replace=false){const q=new URLSearchParams({page,metric,hours:String(hours),session:chartSession,filter:alertFilter});const url='#'+q.toString();if(location.hash!==url)window.history[replace?'replaceState':'pushState'](null,'',url);}
function readURL(){const q=new URLSearchParams(location.hash.slice(1));page=navs.some(n=>n[0]===q.get('page'))?q.get('page'):'overview';metric=Object.hasOwn(labels,q.get('metric'))?q.get('metric'):'temp';hours=[6,24,168,720].includes(+q.get('hours'))?+q.get('hours'):24;chartSession=q.get('session')||'latest';alertFilter=['all','active','acked'].includes(q.get('filter'))?q.get('filter'):'all';}
function morph(old,fresh){
 if(old.nodeType!==fresh.nodeType||old.nodeName!==fresh.nodeName){old.replaceWith(fresh.cloneNode(true));return;}
 if(old.nodeType===3){if(old.nodeValue!==fresh.nodeValue)old.nodeValue=fresh.nodeValue;return;}
 if(old.nodeType!==1)return;
 if(old===document.activeElement && ['SELECT','INPUT','TEXTAREA'].includes(old.tagName))return;
 for(const a of [...old.attributes])if(!fresh.hasAttribute(a.name))old.removeAttribute(a.name);
 for(const a of [...fresh.attributes])if(old.getAttribute(a.name)!==a.value)old.setAttribute(a.name,a.value);
 for(let i=0;i<fresh.childNodes.length;i++){if(old.childNodes[i])morph(old.childNodes[i],fresh.childNodes[i]);else old.append(fresh.childNodes[i].cloneNode(true));}
 while(old.childNodes.length>fresh.childNodes.length)old.lastChild.remove();
}
async function updateLive(){
 if(page==='overview'){
  const t=document.createElement('div');t.innerHTML=overview();
  for(const selector of ['.system-status','.priority-alert','.water-metrics','#control-rows','.operations-bottom']){const a=$(selector),b=t.querySelector(selector);if(a&&b)morph(a,b);}
  if(!document.activeElement?.closest('.chart-card')&&!$('.chart-card:hover'))await loadChart(renderId);
 }else if(page==='controls'){const t=$('#main').cloneNode(false);t.innerHTML=controlsView();morph($('#main'),t);}
 else if(page==='alerts'&&!document.activeElement?.closest('.alert-list')){const t=$('#main').cloneNode(false);t.innerHTML=alertsView();morph($('#main'),t);}
}

function legacyOverview(){
 const active=activeAlerts(),event=active[0]||S.alerts[0],w=weatherData(),hour=w?.hours[0];
 return head('Tổng quan ao nuôi','Theo dõi môi trường, thiết bị và an ninh trong cùng một không gian.',`<button class="btn" data-action="sync">${icon('refresh',13)} Đồng bộ</button><button class="btn primary" data-nav="history">${icon('download',13)} Xuất dữ liệu</button>`)+
 `<div class="overview-strip"><span class="pond-select">${icon('drop',14)} ${esc(S.settings.pondName)}</span><span class="strip-sep"></span><i class="dot ${S.connection.deviceFresh?'':'orange'}"></i><span>${S.mode==='demo'?'ESP32 · mô phỏng':S.connection.deviceFresh&&!pollFailures?'ESP32 · dữ liệu mới':'ESP32 · chưa có dữ liệu mới'}</span><span class="right">${icon('clock',11)} Cập nhật mỗi 5 giây</span></div><div class="metric-grid">${metricCard('temp','thermo')}${metricCard('ph','drop','blue')}${metricCard('turb','waves','amber')}<article class="card metric-card"><div class="metric-top"><span>An ninh ao nuôi</span><span class="metric-icon">${icon('shield',16)}</span></div><div class="metric-value" style="font-size:25px;line-height:1.85">${!fresh('laser')?'Chưa rõ':S.latest.laser?.value?'Xâm nhập':'An toàn'}</div><div class="metric-foot">${pill(!fresh('laser')?'Chưa có dữ liệu mới':S.latest.laser?.value?'Tia bị cắt':'Laser thông suốt',!fresh('laser')?'neutral':S.latest.laser?.value?'critical':'')}<span>Hàng rào laser</span></div></article></div><div class="main-grid">${chartCard()}${controlCard()}</div><div class="bottom-grid"><section class="card"><div class="card-head"><h2>Cảnh báo gần đây</h2><button class="btn link" data-nav="alerts">Xem tất cả ${icon('arrow',12)}</button></div><div class="event-body">${event?`<div class="event-item"><span class="event-symbol">${icon(event.active?'alert':'check',15)}</span><div><strong>${esc(event.title)}</strong><p>${esc(event.detail).slice(0,135)}</p><div class="event-time">${dt(event.createdAt,true)} · ${event.source==='demo'?'Minh họa':event.active?'Đang diễn ra':'Đã kết thúc'}</div></div></div>`:'<div class="empty-small">Chưa ghi nhận cảnh báo.</div>'}</div></section><section class="card"><div class="card-head"><h2>Thời tiết tại ao</h2><button class="btn link" data-nav="weather">Chi tiết ${icon('arrow',12)}</button></div>${hour?`<div class="weather-mini"><span class="weather-icon">${icon('cloud',40)}</span><div><div class="weather-temp">${fmt(hour.airTemp)}<small> °C</small></div><p>${w.sample?'Kịch bản thời tiết minh họa':'Dự báo không khí · '+dt(hour.targetAt)+' · <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a>'}</p></div></div><div class="weather-mini-meta"><span>Độ ẩm ${fmt(hour.humidity,0)}%</span><span>Mưa ${fmt(hour.rain)} mm/h</span><span>Gió ${fmt(hour.wind,0)} km/h</span></div>`:'<div class="event-body empty-small">Cấu hình tọa độ để lấy dự báo thời tiết.</div>'}</section><section class="card"><div class="card-head"><h2>Camera ao nuôi</h2><button class="btn link" data-nav="camera">Mở camera ${icon('arrow',12)}</button></div><div class="camera-thumb">${pondScene()}<span class="camera-label">SƠ ĐỒ MINH HỌA · KHÔNG PHẢI ẢNH TRỰC TIẾP</span></div><div class="camera-bottom"><span>ESP32-CAM / ${S.connection.camera?'Đã cấu hình':'Chưa kết nối'}</span><span>${icon('camera',11)}</span></div></section></div>`+footer();
}
function historyView(){return head('Lịch sử dữ liệu','Tra cứu dữ liệu đo gốc, kiểm tra chất lượng và xuất tập dữ liệu CSV.')+`<section class="card"><div class="toolbar"><label class="field">Chỉ số<select id="history-metric">${Object.entries(labels).map(([k,l])=>`<option value="${k}" ${metric===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Khoảng thời gian<select id="history-hours">${[[6,'6 giờ'],[24,'24 giờ'],[168,'7 ngày'],[720,'30 ngày']].map(([h,l])=>`<option value="${h}" ${hours===h?'selected':''}>${l}</option>`).join('')}</select></label><div class="right"></div><button class="btn primary" data-action="export">${icon('download',13)} Tải CSV</button></div><div class="notice" style="margin:15px 20px">Giữ nguyên thời điểm gốc từ ThingsBoard. Giá trị thiếu lưu <code>null</code>, không thay bằng 0. Dữ liệu độ đục hiện là %, chưa phải NTU.</div><div id="history-table"><div class="empty-state">Đang tải dữ liệu…</div></div></section>`+footer();}
const commandLabels={setPump:'Bơm oxy',setFan:'Quạt nước',setAuto:'Auto'};
const commandStatus={pending:['Đang chờ','warning'],acknowledged:['Đã phản hồi',''],unknown:['Chưa xác định','warning'],failed:['Thất bại','critical'],rejected:['Không khớp','critical']};
function commandTable(){return S.commands.length?`<div class="table-wrap"><table><thead><tr><th>THỜI GIAN</th><th>THIẾT BỊ</th><th>YÊU CẦU</th><th>TRẠNG THÁI</th><th>NGUỒN</th></tr></thead><tbody>${S.commands.map(c=>`<tr><td>${dt(c.createdAt,true)}</td><td>${commandLabels[c.method]}</td><td>${c.requestedValue?'Bật':'Tắt'}</td><td title="${esc(c.error||'')}">${pill(...(commandStatus[c.status]||[c.status,'neutral']))}</td><td>${c.source==='demo'?'Mô phỏng':'ThingsBoard RPC'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">${icon('sliders',25)}<strong>Chưa có lệnh điều khiển</strong><p>Lịch sử sẽ ghi lại yêu cầu và phản hồi từ thiết bị.</p></div>`;}
function controlsView(){return head('Điều khiển thiết bị','Giám sát trạng thái và gửi lệnh đến bộ điều khiển ESP32.')+`<div class="section-grid"><div>${controlCard()}<div class="notice">Bơm và quạt dùng <code>setPump</code>, <code>setFan</code>; bật / tắt tự động dùng <code>setAuto</code>. Lệnh điều khiển tay tự tắt Auto theo firmware hiện tại.</div></div><section class="card panel"><div class="subhead"><h2>Luồng điều khiển</h2>${icon('link',18)}</div><ol class="steps"><li>Web gửi yêu cầu đến backend localhost.</li><li>Backend gọi RPC hai chiều của ThingsBoard.</li><li>ESP32 xử lý và trả về trạng thái boolean.</li><li>Web ghi lịch sử lệnh và đọc lại trạng thái.</li></ol><div class="notice amber">Hết thời gian chờ có nghĩa là chưa xác định kết quả. Web không tự gửi lại lệnh. Phản hồi RPC xác nhận xử lý lệnh, chưa chứng minh motor đã quay.</div></section></div><section class="card"><div class="card-head"><h2>Nhật ký điều khiển</h2><span class="card-desc">30 lệnh gần nhất</span></div>${commandTable()}</section>`+footer();}
function alertsView(){const list=S.alerts.slice().sort((a,b)=>(b.active-a.active)||((b.severity==='critical')-(a.severity==='critical'))).filter(a=>alertFilter==='all'||alertFilter==='active'&&a.active||alertFilter==='acked'&&a.acknowledgedAt);return head('Trung tâm cảnh báo','Theo dõi vượt ngưỡng, tình trạng cảm biến và sự kiện an ninh.')+`<section class="card"><div class="filters">${[['all','Tất cả'],['active','Đang diễn ra'],['acked','Đã xác nhận']].map(([k,l])=>`<button class="filter ${alertFilter===k?'active':''}" data-filter="${k}">${l}</button>`).join('')}</div><div class="alert-list">${list.length?list.map(a=>`<article class="alert-item"><span class="event-symbol">${icon(a.severity==='critical'?'shield':'alert',18)}</span><div class="alert-content"><h3>${esc(a.title)}</h3><p>${esc(a.detail)}</p><small>${dt(a.createdAt,true)} · ${esc(a.source)} · ${a.active?'Đang diễn ra':'Đã kết thúc / thông tin dự báo'}${a.resolvedAt?' · Kết thúc '+dt(a.resolvedAt):''}</small></div><div>${pill(a.severity==='critical'?'Nghiêm trọng':'Lưu ý',a.severity==='critical'?'critical':'warning')}<br>${a.acknowledgedAt?'<small class="card-desc">Đã xác nhận</small>':`<button class="btn small" data-ack="${esc(a._id)}">Đánh dấu đã xem</button>`}</div></article>`).join(''):`<div class="empty-state">${icon('shield',30)}<strong>Không có cảnh báo trong bộ lọc này</strong><p>Cảnh báo mới sẽ xuất hiện khi nhận được dữ liệu phù hợp điều kiện.</p></div>`}</div></section><div class="notice">Xác nhận đã xem không xóa cảnh báo và không tắt còi / relay trên ESP32. Cảnh báo web chưa gửi thêm tin Zalo; Rule Chain hiện tại tiếp tục đảm nhiệm luồng đó.</div>`+footer();}
function weatherView(){const w=weatherData(),s=S.settings,coords=s.latitude===null?'Chưa cấu hình vị trí':`${s.latitude}, ${s.longitude}`;return head('Thời tiết & cảnh báo sớm','Đưa dự báo khí tượng vào việc theo dõi môi trường ao.',`<button class="btn" data-nav="settings">${icon('settings',13)} Vị trí ao</button><button class="btn primary" data-action="weather">${icon('refresh',13)} Lấy dự báo thật</button>`)+`<div class="section-grid"><section class="card panel"><div class="subhead"><h2>Dự báo 24 giờ tới</h2>${pill(w?.sample?'Minh họa':w?(Date.now()-new Date(w.fetchedAt)>10800000?'Dự báo đã cũ':'Open-Meteo'):'Chưa kết nối',w?.sample?'warning':'neutral')}</div><p>${icon('drop',12)} ${esc(coords)}${w?.fetchedAt?' · Lấy lúc '+dt(w.fetchedAt,true):''}</p>${w?.sample?'<div class="notice amber">Số liệu bên dưới là kịch bản minh họa. Nhập tọa độ và bấm Lấy dự báo thật để sử dụng API.</div>':''}${w?`<div class="weather-cards">${w.hours.slice(0,12).filter((_,i)=>i%3===0).map(h=>`<div class="weather-hour"><small>${dt(h.targetAt)}</small><div class="weather-icon">${icon(h.rain>0?'cloud':'sun',28)}</div><strong>${fmt(h.airTemp)}°</strong><p>Mưa ${fmt(h.rain)} mm/h</p><p>Độ ẩm ${fmt(h.humidity,0)}%</p><small>Gió ${fmt(h.wind,0)} km/h</small></div>`).join('')}</div>`:'<div class="empty-state">Chưa có dữ liệu thời tiết. Cần tọa độ và Internet.</div>'}</section><section class="card panel"><h2>Quy tắc cảnh báo sớm</h2><div class="integration"><strong>Mưa lớn</strong><p>Từ ${s.weather.rainMm} mm trong một giờ dự báo.</p></div><div class="integration"><strong>Gió mạnh</strong><p>Từ ${s.weather.windKmh} km/h.</p></div><div class="integration"><strong>Nắng nóng</strong><p>Nhiệt độ không khí từ ${s.weather.hotC} °C.</p></div><div class="notice">Các ngưỡng phục vụ đồ án, cần hiệu chỉnh theo ao thực tế. Thời tiết là dữ liệu bên ngoài, không thay thế cảm biến nước.</div></section></div>${w?`<section class="card"><div class="card-head"><h2>Chi tiết theo giờ</h2><span class="card-desc">${w.sample?'Dữ liệu minh họa':'Nguồn: <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · CC BY 4.0'}</span></div><div class="table-wrap"><table><thead><tr><th>GIỜ VIỆT NAM</th><th>KHÔNG KHÍ</th><th>ĐỘ ẨM</th><th>MƯA / GIỜ</th><th>XÁC SUẤT MƯA</th><th>GIÓ</th></tr></thead><tbody>${w.hours.map(h=>`<tr><td>${dt(h.targetAt,true)}</td><td>${fmt(h.airTemp)} °C</td><td>${fmt(h.humidity,0)}%</td><td>${fmt(h.rain)} mm</td><td>${fmt(h.rainProbability,0)}%</td><td>${fmt(h.wind,0)} km/h</td></tr>`).join('')}</tbody></table></div></section>`:''}`+footer();}
function cameraView(){return head('Camera & an ninh','Xem ESP32-CAM, lưu ảnh tại máy và chuẩn bị dữ liệu nhận diện.',`<button class="btn" data-action="stream" ${!S.connection.camera?'disabled':''}>${icon('camera',13)} ${streaming?'Dừng xem':'Xem trực tiếp'}</button><button class="btn primary" data-action="capture" ${!S.connection.cameraCapture?'disabled':''}>${icon('download',13)} Chụp & lưu ảnh</button>`)+`<div class="section-grid"><section class="card panel"><div class="subhead"><h2>ESP32-CAM / Ao nuôi 01</h2>${pill(streaming?'Đang yêu cầu stream':S.connection.camera?'Đã cấu hình':'Chưa kết nối',streaming?'':'neutral')}</div><div class="camera-large" id="camera-view">${streaming?'<img id="stream-image" src="/api/camera/stream" alt="Luồng ảnh trực tiếp từ ESP32-CAM">':cameraPreview()}<div class="camera-overlay">${streaming?'Luồng MJPEG qua backend localhost.':'Ảnh đã lưu · chưa mở luồng trực tiếp.'}</div></div></section><section class="card panel"><h2>An ninh ao nuôi</h2>${laserStatus()}<h3>Phân tích ảnh</h3><div class="notice amber">Chưa có mô hình nhận diện được nạp. Web không tạo kết quả phát hiện vật thể giả.</div><ol class="steps"><li>Kết nối URL stream và URL capture của camera.</li><li>Chụp ảnh, gán nhãn vật thể bất thường.</li><li>Tạo dataset với tập train / validation / test.</li><li>Huấn luyện và đánh giá mô hình riêng.</li><li>Lưu detection gắn với ảnh và phiên bản model.</li></ol><p>Ảnh lưu trong <code>data/images</code>; MongoDB lưu metadata, không nhét ảnh base64 vào bản ghi cảm biến.</p></section></div><section class="card panel"><div class="subhead"><h2>Ảnh đã chụp</h2><span class="card-desc">${S.media.length} ảnh gần đây · chưa gán nhãn</span></div>${S.media.length?`<div class="gallery">${S.media.map(m=>`<button data-media="${esc(m._id)}"><img src="/api/media/${encodeURIComponent(m._id)}" alt="Ảnh ao chụp lúc ${dt(m.capturedAt)}"><small>${dt(m.capturedAt,true)} · Chưa phân tích</small></button>`).join('')}</div>`:`<div class="empty-state">${icon('camera',30)}<strong>Chưa có ảnh</strong><p>Cấu hình ESP32-CAM trong file .env rồi khởi động lại web.</p></div>`}</section>`+footer();}
function aiView(){const m=S.models.find(x=>x.metric===aiMetric),valid=m?.validation;return head('Phân tích & dự báo','Bắt đầu với mô hình nền và kiểm tra sai số trước khi mở rộng học máy.')+`<div class="section-grid"><section class="card panel"><div class="subhead"><h2>Thử nghiệm dự báo chuỗi thời gian</h2>${pill(S.mode==='demo'?'Học từ dữ liệu giả':'Dữ liệu ThingsBoard',S.mode==='demo'?'warning':'')}</div><div class="toolbar" style="padding:12px 0 20px"><label class="field">Chỉ số dự báo<select id="ai-metric">${Object.entries(labels).map(([k,l])=>`<option value="${k}" ${k===aiMetric?'selected':''}>${l}</option>`).join('')}</select></label><button class="btn primary" data-action="train">${icon('brain',14)} Huấn luyện baseline</button></div><p>Hồi quy tuyến tính theo thời gian, dự báo 6 mốc trong 3 giờ tiếp theo. Yêu cầu ít nhất 60 điểm hợp lệ trải dài tối thiểu 3 giờ; dữ liệu mới nhất không quá 30 phút.</p>${m?`<div class="stat-row"><div class="small-stat"><small>SỐ ĐIỂM HỢP LỆ</small><strong>${m.sampleCount}</strong></div><div class="small-stat"><small>MAE TRÊN TẬP TEST</small><strong>${fmt(valid.mae,3)}<span> ${units[aiMetric]}</span></strong></div><div class="small-stat"><small>MAE GIỮ GIÁ TRỊ CUỐI</small><strong>${fmt(valid.naiveMAE,3)}<span> ${units[aiMetric]}</span></strong></div></div><div class="notice ${valid.mae>valid.naiveMAE?'amber':''}">${valid.mae>valid.naiveMAE?'Baseline đang kém hơn cách giữ nguyên giá trị cuối trên tập test.':'Baseline có MAE thấp hơn hoặc bằng cách giữ giá trị cuối trên tập test này.'} Chưa đủ để kết luận khả năng dự báo ngoài thực tế.</div><div class="table-wrap"><table><thead><tr><th>THỜI ĐIỂM DỰ BÁO</th><th>GIÁ TRỊ ƯỚC TÍNH</th><th>LOẠI</th></tr></thead><tbody>${m.forecasts.map(p=>`<tr><td>${dt(p.targetAt,true)}</td><td>${fmt(p.value,aiMetric==='ph'?2:1)} ${units[aiMetric]}</td><td>${m.source==='demo'?'Từ dữ liệu giả':'Thử nghiệm'}</td></tr>`).join('')}</tbody></table></div><p>Huấn luyện lúc ${dt(m.trainedAt,true)} · ${m.validation.trainCount} train / ${m.validation.testCount} test · tách theo thời gian 80/20.</p>`:'<div class="empty-state">Chưa huấn luyện mô hình cho chỉ số này.</div>'}</section><details class="card panel"><summary>Lộ trình học máy & giới hạn</summary><ol class="steps"><li>Lưu dữ liệu gốc và thông tin hiệu chuẩn.</li><li>Làm sạch, chia tập theo thời gian.</li><li>So sánh baseline với mô hình nâng cao.</li><li>Thêm lịch sử thời tiết đã có tại thời điểm dự báo.</li><li>Theo dõi sai số, drift và phiên bản model.</li></ol><div class="notice amber">Độ ẩm tại ao chưa có cảm biến. Độ ẩm Open-Meteo là độ ẩm không khí từ nguồn thời tiết, được lưu riêng.</div><div class="notice">Các dự báo không tự bật bơm / quạt. Mô hình tuyến tính chỉ là mốc so sánh, chưa mô hình hóa ảnh hưởng của mưa đến pH.</div></details></div>`+footer();}
function settingsView(){const s=S.settings;return head('Cài đặt không gian','Cấu hình ao, ngưỡng theo dõi và các kết nối của hệ thống.')+`<div class="section-grid"><section class="card panel"><div class="subhead"><h2>Thông tin & ngưỡng cảnh báo</h2>${pill(S.mode==='demo'?'Lưu tạm trong RAM':'Lưu MongoDB',S.mode==='demo'?'warning':'')}</div><form id="settings-form"><div class="form-grid"><label class="field full">Tên ao<input name="pondName" value="${esc(s.pondName)}" maxlength="80" required></label><label class="field">Vĩ độ<input name="latitude" type="number" step="any" min="-90" max="90" placeholder="Nhập vĩ độ của ao" value="${s.latitude??''}"></label><label class="field">Kinh độ<input name="longitude" type="number" step="any" min="-180" max="180" placeholder="Nhập kinh độ của ao" value="${s.longitude??''}"></label><div class="form-divider">Ngưỡng cảnh báo trên web</div>${[['tempMin','Nhiệt độ thấp (°C)',-10,80],['tempMax','Nhiệt độ cao (°C)',-10,80],['phMin','pH thấp',0,14],['phMax','pH cao',0,14],['turbMax','Độ đục cao (%)',0,100]].map(([k,l,min,max])=>`<label class="field">${l}<input name="${k}" type="number" min="${min}" max="${max}" step="0.1" required value="${s.thresholds[k]}"></label>`).join('')}<div class="form-divider">Ngưỡng cảnh báo thời tiết</div>${[['rainMm','Mưa lớn (mm/giờ)',1,200],['windKmh','Gió mạnh (km/h)',1,300],['hotC','Nắng nóng (°C)',0,60]].map(([k,l,min,max])=>`<label class="field">${l}<input name="${k}" type="number" min="${min}" max="${max}" step="0.1" required value="${s.weather[k]}"></label>`).join('')}</div><div class="notice">Lưu ngưỡng này chỉ thay đổi cảnh báo của web. Firmware ESP32 vẫn dùng ngưỡng được nạp sẵn. Tọa độ chỉ gửi đến Open-Meteo khi bạn bấm lấy dự báo.</div><p class="dirty-note" id="dirty-note" role="status"></p><button type="submit" class="btn primary">${icon('check',14)} Lưu cài đặt</button></form></section><section class="card panel"><h2>Kết nối hệ thống</h2><div class="integration"><div class="integration-head"><strong>ThingsBoard</strong>${pill(S.mode==='demo'?'Mô phỏng':S.connection.connected?'Đã kết nối':'Chưa kết nối',S.connection.connected?'':'warning')}</div><p>REST API đồng bộ telemetry và RPC hai chiều. Thông tin xác thực chỉ đặt trong .env tại backend.</p></div><div class="integration"><div class="integration-head"><strong>MongoDB</strong>${pill(S.connection.database,S.mode==='demo'?'neutral':'')}</div><p>Chế độ live bắt buộc có MongoDB; không tự chuyển sang RAM khi cơ sở dữ liệu lỗi.</p></div><div class="integration"><div class="integration-head"><strong>ESP32-CAM</strong>${pill(S.connection.camera?'Đã cấu hình':'Chưa cấu hình','neutral')}</div><p>CAMERA_STREAM_URL: http://IP_CAM:81/stream<br>CAMERA_CAPTURE_URL: http://IP_CAM/capture</p></div><details><summary>Chi tiết cấu hình</summary><h3>Thông tin kết nối</h3><pre class="code-block">APP_MODE=live\nMONGODB_URI=mongodb://127.0.0.1:27017\nTB_URL=https://thingsboard.cloud\nTB_DEVICE_ID=…\nTB_USERNAME=…\nTB_PASSWORD=…</pre><p>Không phải device access token. Chỉ nhập bí mật trên máy của nhóm, sau đó khởi động lại backend. Đọc README để cài MongoDB và kiểm tra vùng ThingsBoard.</p></details></section></div><details class="card panel"><summary>Kỹ thuật · Cấu trúc lưu trữ</summary><div class="subhead"><div><h2>Thiết kế MongoDB</h2><p class="card-desc">19 collections · mở rộng nhiều ao, camera và học máy</p></div>${icon('database',20)}</div><div class="schema-grid" id="schema-grid">Đang tải cấu trúc…</div></details>`+footer();}
async function render(){syncURL();const id=++renderId;$('#main').innerHTML=({overview,history:historyView,controls:controlsView,alerts:alertsView,weather:weatherView,camera:cameraView,ai:aiView,settings:settingsView}[page])();chrome();if(page==='overview')await loadChart(id);if(page==='history')await loadHistory(id);if(page==='settings'){try{const d=await api('/api/schema');if(id===renderId)$('#schema-grid').innerHTML=d.collections.map(c=>`<div class="schema-item"><code>${c.name}</code><p>${c.purpose}</p></div>`).join('');}catch(e){toast(e.message,true);}}if(page==='camera'&&streaming){const im=$('#stream-image');im.addEventListener('error',()=>{streaming=false;$('#camera-view').innerHTML='<div class="empty-state"><strong>Không mở được luồng camera</strong><p>Kiểm tra nguồn ESP32-CAM, IP, cổng 81 và kết nối mạng.</p></div>';toast('Không kết nối được ESP32-CAM.',true);});}}
function go(p){if($('#settings-form')?.dataset.dirty==='true'&&!window.confirm('Bạn có thay đổi chưa lưu. Rời trang mà không lưu?'))return;if(!navs.some(n=>n[0]===p))return;if(page==='camera'&&p!=='camera')streaming=false;page=p;historyPage=1;if(hours===720&&p==='overview')hours=24;if(p==='overview'&&!['temp','ph','turb'].includes(metric))metric='temp';render();$('.sidebar').classList.remove('open');window.scrollTo({top:0});}
async function loadChart(id){
 try{
  const requestedMetric=metric,result=await api(`/api/sessions?metric=${requestedMetric}`);
  if(id!==renderId)return;
  const selected=paintSessionControls(result);
  if(!selected){$('#chart-area').innerHTML='<div class="empty-state">Không có đợt đo để hiển thị.</div>';$('#chart-meta').textContent='Tra cứu các đợt trong 7 ngày gần nhất, tối đa 50.000 bản ghi/chỉ số.';return;}
  const d=await api(`/api/history?metric=${requestedMetric}&start=${selected.startTs}&end=${selected.endTs}&limit=50000`);
  if(id!==renderId)return;
  const duration=selected.endTs-selected.startTs,pad=Math.max(30000,duration*.035);
  const start=Math.max(0,selected.startTs-pad),end=selected.endTs+pad;
  $('#chart-area').innerHTML=chartSVG(d.rows,requestedMetric,start,end);
  $('#chart-meta').textContent=`${units[requestedMetric]} · ${d.rows.length.toLocaleString('vi-VN')} bản ghi của đợt này · ${S.mode==='demo'?'mô phỏng':'ThingsBoard'} · ngắt đợt khi gián đoạn > 5 phút${d.truncated?' · đã chạm giới hạn 50.000 điểm':''}`;
  const svg=$('#series-chart');
  if(svg){let idx=0;svg.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();idx=e.key==='Home'?0:e.key==='End'?d.rows.length-1:Math.max(0,Math.min(d.rows.length-1,idx+(e.key==='ArrowRight'?1:-1)));const p=d.rows[idx],tip=$('.chart-tip');tip.textContent=stamp(p.observedAt)+' · '+(p.quality==='valid'?fmt(p.value)+' '+units[requestedMetric]:'Thiếu / lỗi dữ liệu');tip.style.display='block';tip.setAttribute('role','status');});svg.addEventListener('pointermove',e=>{
   if(!d.rows.length)return;
   const r=svg.getBoundingClientRect(),target=start+Math.max(0,Math.min(1,((e.clientX-r.left)/r.width*svg.viewBox.baseVal.width-48)/(svg.viewBox.baseVal.width-70)))*(end-start);
   const p=d.rows.reduce((best,x)=>Math.abs(new Date(x.observedAt)-target)<Math.abs(new Date(best.observedAt)-target)?x:best,d.rows[0]);
   const tip=$('.chart-tip');if(!tip)return;
   tip.textContent=`${stamp(p.observedAt)} · ${p.quality==='valid'?fmt(p.value,requestedMetric==='ph'?2:1)+' '+units[requestedMetric]:'Thiếu / lỗi dữ liệu'}`;
   tip.style.display='block';tip.style.left=Math.min(65,Math.max(4,(e.clientX-r.left)/r.width*100))+'%';
  });svg.addEventListener('pointerleave',()=>{const tip=$('.chart-tip');if(tip)tip.style.display='none';});}
 }catch(e){if(id===renderId){$('#chart-area').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`;$('#chart-meta').textContent='Không tải được đợt đo. Kiểm tra backend đã cập nhật và kết nối MongoDB.';}}
}
function chartSVG(rows,key,start,end){
 const good=rows.filter(p=>p.quality==='valid'&&Number.isFinite(p.value));
 if(!good.length)return '<div class="empty-state">Đợt này chưa có giá trị hợp lệ cho chỉ số đang chọn.</div>';
 let min=Math.min(...good.map(p=>p.value)),max=Math.max(...good.map(p=>p.value)),pad=Math.max((max-min)*.35,key==='ph'?.05:.3);const bounds=waterBounds(key,S.settings.thresholds);min=Math.min(min-pad,bounds[0]??min);max=Math.max(max+pad,bounds[1]??max);
 const plotWidth=Math.max(310,$('#chart-area')?.clientWidth-32||760),plotSpan=plotWidth-70,ticks=plotWidth<500?3:7;const x=t=>48+(new Date(t)-start)/(end-start)*plotSpan,y=v=>180-(v-min)/(max-min)*150;
 const segments=[];let current=[],previous=null;
 // Chia đoạn trước khi lấy bớt điểm: dữ liệu thiếu không biến thành đường nối giả.
 for(const p of rows){
  if(p.quality!=='valid'||!Number.isFinite(p.value)){if(current.length)segments.push(current);current=[];previous=null;continue;}
  if(previous&&new Date(p.observedAt)-new Date(previous.observedAt)>300000){if(current.length)segments.push(current);current=[];}
  current.push([x(p.observedAt),y(p.value)]);previous=p;
 }
 if(current.length)segments.push(current);
 const stride=Math.max(1,Math.ceil(good.length/500));
 const sampled=segments.map(seg=>envelope(seg));
 const boundsY=bounds.map(v=>v===null?null:y(v));const band=boundsY.every(v=>v!==null)?`<rect x="48" y="${boundsY[1]}" width="${plotSpan}" height="${boundsY[0]-boundsY[1]}" fill="#e2f2ec"/><path d="M48 ${boundsY[0]}H${plotWidth-22} M48 ${boundsY[1]}H${plotWidth-22}" stroke="#5b8b7d" stroke-dasharray="6 4"/>`:'';const anomalies=sampled.flat().filter(p=>p[1]<boundsY[1]||p[1]>boundsY[0]).map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#b53d31"/>`).join('');const path=sampled.map(seg=>seg.map(([xx,yy],i)=>(i?'L':'M')+xx.toFixed(2)+','+yy.toFixed(2)).join(' ')).join(' ');
 const fill=sampled.filter(seg=>seg.length>1).map(seg=>`M${seg[0][0]},180 L${seg.map(p=>p.join(',')).join(' L')} L${seg.at(-1)[0]},180 Z`).join(' ');
 const dots=sampled.filter(seg=>seg.length===1).map(seg=>`<circle cx="${seg[0][0]}" cy="${seg[0][1]}" r="3" fill="#6d9164"/>`).join('');
 const tick=t=>end-start>=86400000?dt(t,true):new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',...(end-start<600000?{second:'2-digit'}:{}),hourCycle:'h23',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(t));
 return `<div class="chart-summary"><span>Thấp nhất <b>${fmt(Math.min(...good.map(p=>p.value)),2)}</b></span><span>Cao nhất <b>${fmt(Math.max(...good.map(p=>p.value)),2)}</b></span><span>Trung bình <b>${fmt(good.reduce((a,p)=>a+p.value,0)/good.length,2)}</b></span></div><p class="threshold-caption">Vùng xanh: ngưỡng cài đặt hiện tại · Chấm đỏ: vượt ngưỡng</p><div class="chart-tip"></div><svg tabindex="0" class="chart" id="series-chart" viewBox="0 0 ${plotWidth} 220" role="img" aria-label="Biểu đồ ${esc(labels[key])}, một đợt đo, ${good.length} điểm hợp lệ"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#a9c299" stop-opacity=".27"/><stop offset="100%" stop-color="#cbdac1" stop-opacity=".04"/></linearGradient></defs>${band}${Array.from({length:4},(_,i)=>{const yy=30+i*50;return `<path class="grid" d="M48 ${yy}H${plotWidth-22}"/><text x="6" y="${yy+4}">${fmt(max-i*(max-min)/3,key==='ph'?2:1)}</text>`;}).join('')}<path class="chart-area" d="${fill}"/><path class="chart-line" d="${path}"/>${dots}${anomalies}${Array.from({length:ticks},(_,i)=>`<text x="${48+i*plotSpan/(ticks-1)}" y="207" text-anchor="${i===0?'start':i===ticks-1?'end':'middle'}">${tick(start+i*(end-start)/(ticks-1))}</text>`).join('')}</svg>`;
}

async function loadHistory(id){try{const {start,end}=nowRange(),d=await api(`/api/history?metric=${metric}&start=${start}&end=${end}&limit=50000`);if(id!==renderId)return;lastRows=d.rows.slice().reverse();paintHistory(d.truncated);}catch(e){if(id===renderId)$('#history-table').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`;}}
function paintHistory(truncated=false){const size=20,max=Math.max(1,Math.ceil(lastRows.length/size));historyPage=Math.min(historyPage,max);const rows=lastRows.slice((historyPage-1)*size,historyPage*size);$('#history-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>THỜI ĐIỂM ĐO</th><th>THIẾT BỊ</th><th>CHỈ SỐ</th><th>GIÁ TRỊ</th><th>CHẤT LƯỢNG</th><th>NGUỒN</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${dt(p.observedAt,true)}</td><td>ESP32-01</td><td>${labels[p.metric]}</td><td>${p.value===null?'null':fmt(p.value,p.metric==='ph'?2:1)} ${units[p.metric]}</td><td>${pill(p.quality==='valid'?'Hợp lệ':p.quality==='missing'?'Thiếu':'Không hợp lệ',p.quality==='valid'?'':'warning')}</td><td>${p.source==='demo'?'Mô phỏng':'ThingsBoard'}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${lastRows.length.toLocaleString('vi-VN')} bản ghi${truncated?' · chạm giới hạn 50.000':''}</span><button class="btn small" data-page="-1" ${historyPage<=1?'disabled':''}>Trước</button><span>${historyPage} / ${max}</span><button class="btn small" data-page="1" ${historyPage>=max?'disabled':''}>Sau</button></div>`:`<div class="empty-state">${icon('database',28)}<strong>Chưa có dữ liệu ${labels[metric].toLowerCase()}</strong><p>${metric==='humidity'?'Mạch hiện tại chưa có cảm biến độ ẩm tại ao.':'Thử chọn khoảng thời gian khác hoặc kiểm tra đồng bộ.'}</p></div>`;}
async function refresh(shouldRender=true){try{S=await api('/api/state');pollFailures=0;if($('#connection-lost'))$('#connection-lost').hidden=true;chrome();if(shouldRender)await render();}catch(e){pollFailures++;chrome();let banner=$('#connection-lost');if(!banner){banner=document.createElement('div');banner.id='connection-lost';banner.className='error-banner';banner.setAttribute('role','alert');$('#main').prepend(banner);}banner.hidden=false;banner.textContent='Mất kết nối backend · Dữ liệu đang hiển thị là dữ liệu cũ. Điều khiển đã khóa.';if(pollFailures===1)toast('Mất kết nối backend. Dữ liệu đang hiển thị có thể đã cũ.',true);const rows=$('#control-rows');if(rows)rows.querySelectorAll('button').forEach(b=>b.disabled=true);if(page==='overview'){const t=document.createElement('div');t.innerHTML=overview();for(const selector of ['.system-status','.water-metrics']){if($(selector))morph($(selector),t.querySelector(selector));}}}}
document.addEventListener('click',async e=>{
 const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}
 if(e.target.closest('#menu')){$('.sidebar').classList.toggle('open');return;}
 const latest=e.target.closest('[data-session-latest]'),step=e.target.closest('[data-session-step]');
 if(latest||step){
  if(latest)chartSession='latest';
  else{const index=chartSession==='latest'?chartSessions.length-1:chartSessions.findIndex(x=>x.id===chartSession);const next=index+Number(step.dataset.sessionStep);if(index<0||next<0||next>=chartSessions.length)return;chartSession=next===chartSessions.length-1?'latest':chartSessions[next].id;}
  render();return;
 }
 const mh=e.target.closest('[data-metric]');if(mh){metric=mh.dataset.metric;render();return;}
 const filter=e.target.closest('[data-filter]');if(filter){alertFilter=filter.dataset.filter;render();return;}
 const pg=e.target.closest('[data-page]');if(pg){historyPage+=+pg.dataset.page;paintHistory();return;}
 const media=e.target.closest('[data-media]');if(media){$('#dialog-content').innerHTML=`<img src="/api/media/${encodeURIComponent(media.dataset.media)}" alt="Ảnh từ ESP32-CAM">`;$('#detail-dialog').showModal();return;}
 if(e.target.closest('#close-dialog')){$('#detail-dialog').close();return;}
 const command=e.target.closest('[data-command]');if(command){if(busy)return;if(S.mode==='live'&&command.dataset.command!=='setAuto'&&fresh('auto')&&observed('auto')?.value===1&&!window.confirm('Thao tác này sẽ tắt Auto trên ESP32 và chuyển sang điều khiển tay. Tiếp tục?'))return;busy=true;$$('[data-command]').forEach(b=>b.disabled=true);command.textContent='Đang gửi…';toast('Đang chờ phản hồi thiết bị…');try{const c=await api('/api/commands',{method:command.dataset.command,value:command.dataset.value==='true',idempotencyKey:crypto.randomUUID()});toast(c.status==='acknowledged'?(S.mode==='demo'?'Đã cập nhật công tắc mô phỏng.':'ESP32 đã phản hồi lệnh.'):'Thiết bị phản hồi khác yêu cầu.',c.status!=='acknowledged');}catch(err){toast(err.message,true);}finally{busy=false;await refresh();}return;}
 const ack=e.target.closest('[data-ack]');if(ack){ack.disabled=true;try{await api('/api/alerts/'+encodeURIComponent(ack.dataset.ack),{});await refresh();toast('Đã xác nhận xem cảnh báo.');}catch(err){toast(err.message,true);ack.disabled=false;}return;}
 const action=e.target.closest('[data-action]');if(!action)return;const a=action.dataset.action;
 if(a==='export'){const {start,end}=nowRange();window.location.assign(`/api/export?metric=${metric}&start=${start}&end=${end}`);return;}
 if(a==='stream'){streaming=!streaming;render();return;}
 action.disabled=true;
 try{if(a==='sync'){const d=await api('/api/sync',{});if(!d.ok)throw Error(d.status?.error||'Đồng bộ thất bại.');toast('Đã đồng bộ dữ liệu.');}
 if(a==='weather'){await api('/api/weather/refresh',{});toast('Đã lấy dự báo Open-Meteo.');}
 if(a==='capture'){await api('/api/camera/capture',{});toast('Đã lưu ảnh. Chưa chạy nhận diện.');}
 if(a==='train'){await api('/api/models/train',{metric:aiMetric});toast('Đã huấn luyện và lưu phiên bản baseline.');}
 await refresh();}catch(err){toast(err.message,true);}finally{action.disabled=false;}
});
document.addEventListener('change',e=>{if(e.target.id==='chart-session'){chartSession=e.target.value;render();return;}if(e.target.id==='history-metric'){metric=e.target.value;historyPage=1;render();}if(e.target.id==='history-hours'){hours=+e.target.value;historyPage=1;render();}if(e.target.id==='ai-metric'){aiMetric=e.target.value;render();}});
document.addEventListener('submit',async e=>{if(e.target.id!=='settings-form')return;e.preventDefault();const f=new FormData(e.target),num=k=>Number(f.get(k)),b={pondName:f.get('pondName'),latitude:f.get('latitude')===''?null:num('latitude'),longitude:f.get('longitude')===''?null:num('longitude'),thresholds:Object.fromEntries(['tempMin','tempMax','phMin','phMax','turbMax'].map(k=>[k,num(k)])),weather:Object.fromEntries(['rainMm','windKmh','hotC'].map(k=>[k,num(k)]))};const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{await api('/api/settings',b);await refresh();toast('Đã lưu cài đặt'+(S.mode==='demo'?' trong RAM của phiên mô phỏng.':'.'));}catch(err){toast(err.message,true);submit.disabled=false;}});

document.addEventListener('input',e=>{const f=e.target.closest('#settings-form');if(!f)return;f.dataset.dirty='true';$('#dirty-note').textContent='Có thay đổi chưa lưu';e.target.setCustomValidity('');const note=e.target.parentElement.querySelector('.field-error');if(note)note.textContent='';const t=f.elements;for(const prefix of ['temp','ph']){t[prefix+'Max'].setCustomValidity(Number(t[prefix+'Max'].value)<=Number(t[prefix+'Min'].value)?'Ngưỡng trên phải lớn hơn ngưỡng dưới.':'');}const a=t.latitude,b=t.longitude;const missing=(a.value==='')!==(b.value==='');a.setCustomValidity(missing?'Nhập đủ cả vĩ độ và kinh độ.':'');b.setCustomValidity(missing?'Nhập đủ cả vĩ độ và kinh độ.':'');});
document.addEventListener('invalid',e=>{if(!e.target.closest('#settings-form'))return;let note=e.target.parentElement.querySelector('.field-error');if(!note){note=document.createElement('p');note.className='field-error';e.target.after(note);}note.textContent=e.target.validationMessage;},true);
window.addEventListener('beforeunload',e=>{if($('#settings-form')?.dataset.dirty==='true'){e.preventDefault();e.returnValue='';}});

readURL();window.addEventListener('popstate',()=>{if($('#settings-form')?.dataset.dirty==='true'&&!window.confirm('Bạn có thay đổi chưa lưu. Rời trang mà không lưu?')){syncURL(true);return;}readURL();render();});document.addEventListener('click',e=>{if(e.target.closest('#more-menu'))$('.sidebar').classList.toggle('open');});try{S=await api('/api/state');shell();}catch(e){$('#app').innerHTML=`<div class="loading"><h1>Chưa kết nối được máy chủ</h1><p>${esc(e.message)}</p><p>Chạy npm start rồi mở http://localhost:3000.</p></div>`;}
setInterval(async()=>{if(!S||busy||document.hidden)return;const choosingSession=page==='overview'&&document.activeElement?.closest('#session-controls');const auto=['overview','alerts','controls'].includes(page)&&!choosingSession;await refresh(false);if(auto&&!pollFailures)await updateLive();},5000);
